<?php declare(strict_types=1);require dirname(__DIR__,2).'/includes/bootstrap.php';require_permission('reports.view');$from=(string)input('from',date('Y-m-d',strtotime('-30 days')));$to=(string)input('to',date('Y-m-d'));if(!valid_date($from)||!valid_date($to)){$from=date('Y-m-d',strtotime('-30 days'));$to=date('Y-m-d');flash('error','Invalid report date range.');}$stmt=db()->prepare('SELECT t.transaction_id,u.name,u.mobile,t.type,t.amount,t.status,t.reference,t.created_at FROM wallet_transactions t JOIN users u ON u.id=t.user_id WHERE t.created_at>=? AND t.created_at<DATE_ADD(?,INTERVAL 1 DAY) ORDER BY t.id DESC LIMIT 5000');$stmt->execute([$from,$to]);$rows=$stmt->fetchAll();if(input('export')==='csv'){require_permission('reports.export');header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="transactions-'.$from.'-'.$to.'.csv"');$out=fopen('php://output','w');fputcsv($out,['Transaction ID','User','Mobile','Type','Amount','Status','Reference','Date'],',','"','\\');foreach($rows as $r)fputcsv($out,csv_row($r),',','"','\\');audit_log((int)admin()['id'],'REPORT_EXPORT','reports','transactions',null,['from'=>$from,'to'=>$to,'rows'=>count($rows)]);exit;}$pageTitle='Transaction report';require APP_ROOT.'/includes/header.php';?>
<section class="panel"><div class="panel-head"><h2>Transaction activity</h2><div class="actions"><a href="<?=e(app_url('/admin/reports/users.php'))?>">Users</a><a href="<?=e(app_url('/admin/reports/withdrawals.php'))?>">Withdrawals</a></div></div><form class="filters"><input type="date" name="from" value="<?=e($from)?>"><input type="date" name="to" value="<?=e($to)?>"><button class="btn">Run report</button><?php if(can('reports.export')):?><button class="btn secondary" name="export" value="csv">Export CSV</button><?php endif?></form><div class="table-wrap"><table><thead><tr><th>Transaction</th><th>User</th><th>Type</th><th>Amount</th><th>Status</th><th>Reference</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['transaction_id'])?></td><td><?=e($r['name'])?></td><td><?=e($r['type'])?></td><td><?=money($r['amount'])?></td><td><span class="badge <?=strtolower(e($r['status']))?>"><?=e($r['status'])?></span></td><td><?=e($r['reference']??'—')?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach?></tbody></table></div></section><?php require APP_ROOT.'/includes/footer.php';
